#include "ClinicalAssetGate.h"
#include <algorithm>
namespace dnxr { namespace { bool banned(std::string t){ std::transform(t.begin(),t.end(),t.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));}); const char* bad[]={"combat","chute","fall","noyade","drowning","suffocation","horreur","horror","claustrophobie","pain","douleur","fire","feu","explosion","poursuite","addictive","mmorpg"}; for(auto b:bad) if(t.find(b)!=std::string::npos) return true; return false; } }
ClinicalAssetDecision ClinicalAssetGate::validate(const ClinicalSceneAsset& a) const { if(!a.signedContract) return {false,"scene_contract_unsigned"}; if(!a.realityAnchorAvailable) return {false,"reality_anchor_absent"}; if(!a.neutralExitAvailable) return {false,"neutral_exit_absent"}; for(const auto& t:a.tags) if(banned(t)) return {false,"clinical_asset_tag_blocked"}; if(!a.contract.acceptableForClinical(1.0f,true,true)) return {false,"scene_capability_contract_rejected"}; return {true,"clinical_asset_allowed"}; } }
